namespace CodeChops.Idioma.Generators;

/// <summary>
/// Helpers the analyzers share, such as telling the user's own code from generated code.
/// </summary>
internal static class AnalyzerSupport
{
    /// <summary>
    /// Whether code is the user's own: not generated, or generated by Razor from the user's markup.
    /// </summary>
    public static bool IsHandWritten(bool isGeneratedCode, SyntaxTree tree)
    {
        // Razor names its output after the markup file: Pages/Index.cshtml becomes Pages/Index_cshtml.g.cs.
        var path = tree.FilePath;

        var isHandWritten = !isGeneratedCode
                            || path.EndsWith("_razor.g.cs", StringComparison.Ordinal)
                            || path.EndsWith("_cshtml.g.cs", StringComparison.Ordinal)
                            || IsRazorDeclaration(tree);

        return isHandWritten;
    }

    /// <summary>
    /// Whether Razor wrote a file of declarations from a component's <c>@code</c> block, such as
    /// <c>Pages/Index_razor.decl.g.cs</c>. Other source generators see that file.
    /// </summary>
    public static bool IsRazorDeclaration(SyntaxTree tree)
    {
        var path = tree.FilePath;

        var isRazorDeclaration = path.EndsWith("_razor.decl.g.cs", StringComparison.Ordinal)
                                 || path.EndsWith("_cshtml.decl.g.cs", StringComparison.Ordinal);

        return isRazorDeclaration;
    }

    /// <summary>
    /// The types that hold a member, the nearest first. An extension member's method lies in a block inside the static
    /// class that holds it, so that class comes second.
    /// </summary>
    public static IEnumerable<INamedTypeSymbol> GetContainingTypes(ISymbol member)
    {
        for (var type = member.ContainingType; type is not null; type = type.ContainingType)
            yield return type;
    }

    /// <summary>
    /// Whether a method is the generated factory, <c>LocalizedText.Inline</c>.
    /// </summary>
    public static bool IsFactory(IMethodSymbol method)
    {
        var isFactory = String.Equals(method.Name, LocalizedTextFactoryGenerator.FactoryName, StringComparison.Ordinal)
                        && GetContainingTypes(method).Any(static type => String.Equals(type.Name, LocalizedTextFactoryGenerator.ClassName, StringComparison.Ordinal));

        return isFactory;
    }

    /// <summary>
    /// Whether a method is the <c>GetText()</c> the source generator writes for an enum with <c>[Localized]</c> members.
    /// </summary>
    public static bool IsGetTextOfLocalizedMembers(IMethodSymbol method)
    {
        var isGetText = String.Equals(method.Name, LocalizedMembers.ExtensionName, StringComparison.Ordinal)
                        && GetContainingTypes(method).Any(static type => type.Name.EndsWith(LocalizedMembers.ExtensionHolderSuffix, StringComparison.Ordinal));

        return isGetText;
    }

    /// <summary>
    /// The parameter an argument of an attribute takes: the one it names, or else the one of its place. <see langword="null"/>
    /// for a named property, as in <c>Name = ...</c>, and for an argument past the parameters.
    /// </summary>
    public static string? FindParameterOfArgument(SeparatedSyntaxList<AttributeArgumentSyntax> arguments, int index, IMethodSymbol constructor)
    {
        var argument = arguments[index];

        var parameter = argument.NameColon?.Name.Identifier.ValueText
                        ?? (argument.NameEquals is null && index < constructor.Parameters.Length ? constructor.Parameters[index].Name : null);

        return parameter;
    }

    /// <summary>
    /// The language of a set as a message names it, such as <c>'nl'</c>, or <c>that language</c> where the build reads
    /// none.
    /// </summary>
    // Only where a diagnostic is reported, because it may bind the classes the set derives from.
    public static string DescribeLanguage(INamedTypeSymbol set, Compilation compilation, CancellationToken cancellationToken)
    {
        var language = LocalizationDiscovery.ReadLanguage(set, compilation, cancellationToken) is { } code
            ? $"'{code}'"
            : "that language";

        return language;
    }

    /// <summary>
    /// The name of the text a member implements, without the contract an explicit implementation carries in front of it:
    /// <c>Checkout</c> for <c>IShopLocalization.Checkout</c>.
    /// </summary>
    public static string GetTextName(ISymbol member)
    {
        var name = LocalizationDiscovery.GetSimpleName(member.Name);
        return name;
    }
}
